    47	const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
    48	  const hal = createServer({
    49	    app: (() => undefined) as unknown as Express,
    50	    wsAuth: async () => ({id: userId}),
    51	    sessionStore: store,
    52	    orchestrator: answeringOrchestrator,
    53	  });
    54	  await hal.start(0);
    55	  servers.push(hal);
    56	  const {port} = hal.server.address() as AddressInfo;
    57	  return `ws://127.0.0.1:${port}/hal/ws`;
    58	};
