    60	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
    61	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    62	  clients.push(client);
    63	  const frames: Frame[] = [];
    64	  let connected: Frame = {type: ''};
    65	  await new Promise<void>(resolve => {
    66	    client.on('message', raw => {
    67	      const frame = JSON.parse(String(raw)) as Frame;
    68	      if (frame.type === 'connected') {
    69	        connected = frame;
    70	        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    71	        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    72	        return;
    73	      }
    74	      if (frame.type === 'pong') {
    75	        resolve();
    76	        return;
    77	      }
    78	      frames.push(frame);
    79	    });
    80	  });
    81	  return {connected, frames};
    82	};
